		/// <summary>
		/// Lets you efficiently bulk insert many entities to the database.
		/// </summary>
		/// <param name="transactionManager">The transaction manager.</param>
		/// <param name="entities">The entities.</param>
		/// <remarks>
		///		After inserting into the datasource, the MAT.Entities.Factura object will be updated
		/// 	to refelect any changes made by the datasource. (ie: identity or computed columns)
		/// </remarks>	
		public override void BulkInsert(TransactionManager transactionManager, TList<MAT.Entities.Factura> entities)
		{
			//System.Data.SqlClient.SqlBulkCopy bulkCopy = new System.Data.SqlClient.SqlBulkCopy(this._connectionString, System.Data.SqlClient.SqlBulkCopyOptions.CheckConstraints); //, null);
			
			System.Data.SqlClient.SqlBulkCopy bulkCopy = null;
	
			if (transactionManager != null && transactionManager.IsOpen)
			{			
				System.Data.SqlClient.SqlConnection cnx = transactionManager.TransactionObject.Connection as System.Data.SqlClient.SqlConnection;
				System.Data.SqlClient.SqlTransaction transaction = transactionManager.TransactionObject as System.Data.SqlClient.SqlTransaction;
				bulkCopy = new System.Data.SqlClient.SqlBulkCopy(cnx, System.Data.SqlClient.SqlBulkCopyOptions.CheckConstraints, transaction); //, null);
			}
			else
			{
				bulkCopy = new System.Data.SqlClient.SqlBulkCopy(this._connectionString, System.Data.SqlClient.SqlBulkCopyOptions.CheckConstraints); //, null);
			}
			
			bulkCopy.BulkCopyTimeout = 360;
			bulkCopy.DestinationTableName = "Factura";
			
			DataTable dataTable = new DataTable();
			DataColumn col0 = dataTable.Columns.Add("FacturaID", typeof(System.Guid));
			col0.AllowDBNull = false;		
			DataColumn col1 = dataTable.Columns.Add("NroFactura", typeof(System.String));
			col1.AllowDBNull = true;		
			DataColumn col2 = dataTable.Columns.Add("Monto", typeof(System.Double));
			col2.AllowDBNull = true;		
			DataColumn col3 = dataTable.Columns.Add("Fecha", typeof(System.DateTime));
			col3.AllowDBNull = true;		
			DataColumn col4 = dataTable.Columns.Add("Tipo", typeof(System.Int32));
			col4.AllowDBNull = true;		
			DataColumn col5 = dataTable.Columns.Add("Estado", typeof(System.Int32));
			col5.AllowDBNull = true;		
			DataColumn col6 = dataTable.Columns.Add("ClienteID", typeof(System.Guid));
			col6.AllowDBNull = false;		
			DataColumn col7 = dataTable.Columns.Add("VendedorID", typeof(System.Guid));
			col7.AllowDBNull = false;		
			DataColumn col8 = dataTable.Columns.Add("DescuentoAplicado", typeof(System.Double));
			col8.AllowDBNull = false;		
			DataColumn col9 = dataTable.Columns.Add("Observaciones", typeof(System.String));
			col9.AllowDBNull = true;		
			DataColumn col10 = dataTable.Columns.Add("DiasPreReserva", typeof(System.Int32));
			col10.AllowDBNull = true;		
			
			bulkCopy.ColumnMappings.Add("FacturaID", "FacturaID");
			bulkCopy.ColumnMappings.Add("NroFactura", "NroFactura");
			bulkCopy.ColumnMappings.Add("Monto", "Monto");
			bulkCopy.ColumnMappings.Add("Fecha", "Fecha");
			bulkCopy.ColumnMappings.Add("Tipo", "Tipo");
			bulkCopy.ColumnMappings.Add("Estado", "Estado");
			bulkCopy.ColumnMappings.Add("ClienteID", "ClienteID");
			bulkCopy.ColumnMappings.Add("VendedorID", "VendedorID");
			bulkCopy.ColumnMappings.Add("DescuentoAplicado", "DescuentoAplicado");
			bulkCopy.ColumnMappings.Add("Observaciones", "Observaciones");
			bulkCopy.ColumnMappings.Add("DiasPreReserva", "DiasPreReserva");
			
			foreach(MAT.Entities.Factura entity in entities)
			{
				if (entity.EntityState != EntityState.Added)
					continue;
					
				DataRow row = dataTable.NewRow();
				
					row["FacturaID"] = entity.FacturaId;
							
				
					row["NroFactura"] = entity.NroFactura;
							
				
					row["Monto"] = entity.Monto.HasValue ? (object) entity.Monto  : System.DBNull.Value;
							
				
					row["Fecha"] = entity.Fecha.HasValue ? (object) entity.Fecha  : System.DBNull.Value;
							
				
					row["Tipo"] = entity.Tipo.HasValue ? (object) entity.Tipo  : System.DBNull.Value;
							
				
					row["Estado"] = entity.Estado.HasValue ? (object) entity.Estado  : System.DBNull.Value;
							
				
					row["ClienteID"] = entity.ClienteId;
							
				
					row["VendedorID"] = entity.VendedorId;
							
				
					row["DescuentoAplicado"] = entity.DescuentoAplicado;
							
				
					row["Observaciones"] = entity.Observaciones;
							
				
					row["DiasPreReserva"] = entity.DiasPreReserva.HasValue ? (object) entity.DiasPreReserva  : System.DBNull.Value;
							
				
				dataTable.Rows.Add(row);
			}		
			
			// send the data to the server		
			bulkCopy.WriteToServer(dataTable);		
			
			// update back the state
			foreach(MAT.Entities.Factura entity in entities)
			{
				if (entity.EntityState != EntityState.Added)
					continue;
			
				entity.AcceptChanges();
			}
		}
				
